// THE PERFECT LAP — receipt no. 067
// A racing prototype hot-lapping a mountain circuit, drawn entirely with p5.
import JsBarcode from "jsbarcode";

export const receipt = {
  height: 624, // 240–2000 px. Width is fixed by the printer.
  seed: 67,
};

const W = 384;
const M = 37; // side margin
const INK = 0;

export function drawReceipt(p) {
  p.background(255);
  p.noStroke();
  p.fill(INK);

  // ---- header ----
  p.textFont("monospace");
  p.textStyle(p.BOLD);
  p.textSize(19);
  p.textAlign(p.LEFT, p.CENTER);
  p.text("RECEIPT!", M, 53);
  p.textAlign(p.RIGHT, p.CENTER);
  p.text("NO. 067", W - M, 53);
  dashedLine(p, M, 74, W - M, 74, 4, 3);

  // ---- illustration (authored in a 755 x 475 box, scaled to fit) ----
  p.push();
  p.translate(34, 204);
  p.scale(0.4197);
  p.translate(-152, -485);
  p.drawingContext.save();
  p.drawingContext.beginPath();
  p.drawingContext.rect(152, 485, 755, 475);
  p.drawingContext.clip();
  drawScene(p);
  p.drawingContext.restore();
  p.pop();

  // ---- footer ----
  p.noStroke();
  p.fill(INK);
  p.textStyle(p.NORMAL);
  p.textAlign(p.CENTER, p.CENTER);
  p.textSize(18);
  p.text("THE PERFECT LAP", W / 2, 442);
  p.textSize(15);
  p.text("01:42.883", W / 2, 467);
  p.textSize(12);
  p.textStyle(p.BOLD);
  p.text("HACK CLUB", W / 2, 547);
  drawBarcode(p, "HACKCLUB-067-0142883", M, 562, W - 2 * M, 22);
}


/* ------------------------------------------------------------------ */
/* scene: the illustration is a vector trace of the reference art,      */
/* stored as one SVG path (2x units) and filled by p5's canvas context. */
/* ------------------------------------------------------------------ */

function drawScene(p) {
  const ctx = p.drawingContext;
  ctx.save();
  ctx.translate(152, 485);
  ctx.scale(0.5, 0.5);
  ctx.fillStyle = '#000';
  ctx.fill(new Path2D(SCENE_PATH), 'evenodd');
  ctx.restore();
}

